function escapeText(value){const el=document.createElement('span');el.textContent=value;return el.innerHTML}
async function renderList(){
 app.innerHTML='<header><h1>Workboard</h1></header><form id="create-form"><label for="project-name">Project name</label><input id="project-name" name="name" type="text" autocomplete="off"><button type="submit">Create project</button><p class="alert" role="alert" aria-live="polite"></p></form><section class="rows" aria-label="Projects"></section>';
